using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the AI:ApiKey configuration value or OPENAI_API_KEY environment variable.");

var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(sp =>
    new OpenAIChatClient(
        new OpenAI.OpenAIClient(apiKey).GetChatClient(modelId)));

builder.Services.AddSingleton<NoteStore>();

var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var noteStore = host.Services.GetRequiredService<NoteStore>();
var researchTools = new ResearchTools(noteStore);

var tools = new List<AITool>
{
    AIFunctionFactory.Create(researchTools.SearchWeb),
    AIFunctionFactory.Create(researchTools.TakeNote),
    AIFunctionFactory.Create(researchTools.GetNotes),
};

var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research agent. Given a topic, you search the web for relevant information,
        take structured notes on your findings, and then produce a concise summary.

        Workflow:
        1. Search the web for the topic (use multiple queries if needed).
        2. Take notes on each relevant finding.
        3. After gathering enough information, produce a final summary of your notes.

        Always cite the source URL when taking notes.
        """,
    name: "ResearchAgent",
    description: "An agent that researches topics by searching the web and taking notes.",
    tools: tools);

Console.WriteLine("Research Agent Starting...");
Console.Write("Enter a topic to research: ");
var topic = Console.ReadLine()?.Trim();

if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

await foreach (var update in agent.RunStreamingAsync(
    $"Research the following topic and provide a summary: {topic}"))
{
    if (!string.IsNullOrEmpty(update.Text))
    {
        Console.Write(update.Text);
    }
}

Console.WriteLine();

if (noteStore.Notes.Count > 0)
{
    Console.WriteLine("\n--- Research Notes ---");
    foreach (var note in noteStore.Notes)
    {
        Console.WriteLine($"• [{note.Source}] {note.Content}");
    }
}

// --- Tool definitions ---

public sealed class NoteStore
{
    public List<ResearchNote> Notes { get; } = [];
}

public sealed record ResearchNote(string Content, string Source);

public sealed class ResearchTools(NoteStore noteStore)
{
    [Description("Search the web for information on a given query. Returns a list of search results with titles, snippets, and URLs.")]
    public IReadOnlyList<SearchResult> SearchWeb(
        [Description("The search query to look up on the web")] string query)
    {
        // Simulated web search results for demonstration.
        // Replace with a real search API (e.g., Bing Search API) in production.
        return
        [
            new SearchResult(
                $"Overview of {query} - Wikipedia",
                $"https://en.wikipedia.org/wiki/{Uri.EscapeDataString(query)}",
                $"Comprehensive overview covering the history, key concepts, and current state of {query}."),
            new SearchResult(
                $"{query}: Latest Developments - TechNews",
                $"https://technews.example.com/{Uri.EscapeDataString(query.ToLowerInvariant())}",
                $"Recent advances and breakthroughs in {query}, including expert opinions and future predictions."),
            new SearchResult(
                $"Understanding {query} - Research Journal",
                $"https://journal.example.org/articles/{Uri.EscapeDataString(query.ToLowerInvariant())}",
                $"Peer-reviewed research discussing methodologies and findings related to {query}."),
        ];
    }

    [Description("Save a research note with content and source URL for later summarization.")]
    public string TakeNote(
        [Description("The content of the note summarizing a finding")] string content,
        [Description("The source URL where this information was found")] string source)
    {
        noteStore.Notes.Add(new ResearchNote(content, source));
        return $"Note saved. Total notes: {noteStore.Notes.Count}";
    }

    [Description("Retrieve all notes taken so far during the research session.")]
    public IReadOnlyList<ResearchNote> GetNotes()
    {
        return noteStore.Notes;
    }
}

public sealed record SearchResult(string Title, string Url, string Snippet);

